CREATE TABLE IF NOT EXISTS roles (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL,
 role TEXT NOT NULL REFERENCES roles(id), phone TEXT NOT NULL DEFAULT '', "discountType" TEXT NOT NULL DEFAULT 'none',
 "discountStatus" TEXT NOT NULL DEFAULT 'none', "discountEvidence" TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), "createdAt" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS sessions ("tokenHash" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,"expiresAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS password_resets ("tokenHash" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES users(id),"expiresAt" TEXT NOT NULL,"usedAt" TEXT);
CREATE TABLE IF NOT EXISTS stops (id TEXT PRIMARY KEY,name TEXT NOT NULL,address TEXT NOT NULL DEFAULT '',lat DOUBLE PRECISION NOT NULL,lng DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS routes (id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,origin TEXT NOT NULL,destination TEXT NOT NULL,"distanceKm" DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK("distanceKm">=0),price INTEGER NOT NULL CHECK(price>=0),"durationMinutes" INTEGER NOT NULL CHECK("durationMinutes">0),active INTEGER NOT NULL DEFAULT 1);
ALTER TABLE routes ADD COLUMN IF NOT EXISTS "distanceKm" DOUBLE PRECISION NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS route_stops ("routeId" TEXT NOT NULL REFERENCES routes(id),"stopId" TEXT NOT NULL REFERENCES stops(id),"stopOrder" INTEGER NOT NULL,PRIMARY KEY("routeId","stopId"),UNIQUE("routeId","stopOrder"));
CREATE TABLE IF NOT EXISTS buses (id TEXT PRIMARY KEY,code TEXT NOT NULL DEFAULT '',type TEXT NOT NULL DEFAULT 'standard',plate TEXT NOT NULL UNIQUE,name TEXT NOT NULL,"seatCount" INTEGER NOT NULL CHECK("seatCount" BETWEEN 1 AND 100),status TEXT NOT NULL DEFAULT 'active');
ALTER TABLE buses ADD COLUMN IF NOT EXISTS code TEXT NOT NULL DEFAULT '';
ALTER TABLE buses ADD COLUMN IF NOT EXISTS type TEXT NOT NULL DEFAULT 'standard';
UPDATE buses SET code=id WHERE code='';
CREATE UNIQUE INDEX IF NOT EXISTS buses_code_unique ON buses(code);
CREATE TABLE IF NOT EXISTS drivers (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE REFERENCES users(id),"licenseNumber" TEXT NOT NULL DEFAULT '',"licenseClass" TEXT NOT NULL DEFAULT 'D',"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS seats (id TEXT PRIMARY KEY,"busId" TEXT NOT NULL REFERENCES buses(id),number INTEGER NOT NULL CHECK(number>0),UNIQUE("busId",number));
CREATE TABLE IF NOT EXISTS schedules (id TEXT PRIMARY KEY,"routeId" TEXT NOT NULL REFERENCES routes(id),"busId" TEXT NOT NULL REFERENCES buses(id),"driverId" TEXT NOT NULL REFERENCES users(id),"startDate" TEXT NOT NULL,"endDate" TEXT NOT NULL,"firstDeparture" TEXT NOT NULL,"lastDeparture" TEXT NOT NULL,"frequencyMinutes" INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),"createdAt" TEXT NOT NULL);
ALTER TABLE schedules ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'active';
CREATE TABLE IF NOT EXISTS fare_versions (id TEXT PRIMARY KEY,"routeId" TEXT NOT NULL REFERENCES routes(id),price INTEGER NOT NULL CHECK(price>=0),"effectiveFrom" TEXT NOT NULL,"effectiveTo" TEXT,"createdBy" TEXT REFERENCES users(id),"createdAt" TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS fare_versions_route_effective ON fare_versions("routeId","effectiveFrom");
CREATE TABLE IF NOT EXISTS trips (id TEXT PRIMARY KEY,"routeId" TEXT NOT NULL REFERENCES routes(id),"busId" TEXT NOT NULL REFERENCES buses(id),"driverId" TEXT NOT NULL REFERENCES users(id),"scheduleId" TEXT REFERENCES schedules(id),"departureTime" TEXT NOT NULL,"arrivalTime" TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','running','completed','cancelled')),lat DOUBLE PRECISION,lng DOUBLE PRECISION,"locationUpdatedAt" TEXT,"locationSource" TEXT NOT NULL DEFAULT 'simulation');
CREATE TABLE IF NOT EXISTS assignments (id TEXT PRIMARY KEY,"tripId" TEXT NOT NULL UNIQUE REFERENCES trips(id),"busId" TEXT NOT NULL REFERENCES buses(id),"driverId" TEXT NOT NULL REFERENCES users(id),"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vouchers (id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',percent INTEGER NOT NULL DEFAULT 0 CHECK(percent BETWEEN 0 AND 100),"maxDiscount" INTEGER NOT NULL DEFAULT 0,"expiresAt" TEXT NOT NULL,"usageLimit" INTEGER NOT NULL CHECK("usageLimit">0),"usedCount" INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,type TEXT NOT NULL DEFAULT 'percent' CHECK(type IN ('percent','fixed')),value INTEGER NOT NULL DEFAULT 0,"startsAt" TEXT NOT NULL DEFAULT '2000-01-01T00:00:00.000Z',"minAmount" INTEGER NOT NULL DEFAULT 0,"perUserLimit" INTEGER NOT NULL DEFAULT 1 CHECK("perUserLimit">0));
ALTER TABLE vouchers ADD COLUMN IF NOT EXISTS "perUserLimit" INTEGER NOT NULL DEFAULT 1;
ALTER TABLE vouchers ADD COLUMN IF NOT EXISTS name TEXT NOT NULL DEFAULT '';
ALTER TABLE vouchers ADD COLUMN IF NOT EXISTS description TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS bookings (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL,total INTEGER NOT NULL CHECK(total>=0),subtotal INTEGER NOT NULL DEFAULT 0,"discountAmount" INTEGER NOT NULL DEFAULT 0,"voucherId" TEXT REFERENCES vouchers(id),"createdAt" TEXT NOT NULL);
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS subtotal INTEGER NOT NULL DEFAULT 0;
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS "discountAmount" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS "voucherId" TEXT REFERENCES vouchers(id);
CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES users(id),"tripId" TEXT NOT NULL REFERENCES trips(id),"bookingId" TEXT REFERENCES bookings(id),seat INTEGER NOT NULL CHECK(seat>0),status TEXT NOT NULL CHECK(status IN ('held','paid','checked_in','cancelled','expired')),price INTEGER NOT NULL CHECK(price>=0),"basePrice" INTEGER NOT NULL DEFAULT 0,"discountAmount" INTEGER NOT NULL DEFAULT 0,code TEXT NOT NULL UNIQUE,"holdExpiresAt" TEXT,"paymentMethod" TEXT,"refundStatus" TEXT NOT NULL DEFAULT 'none',"createdAt" TEXT NOT NULL,"paidAt" TEXT,"voucherId" TEXT REFERENCES vouchers(id),"cancelReason" TEXT,"changedAt" TEXT);
ALTER TABLE tickets ADD COLUMN IF NOT EXISTS "discountAmount" INTEGER NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX IF NOT EXISTS tickets_active_seat ON tickets("tripId",seat) WHERE status IN ('held','paid','checked_in');
CREATE INDEX IF NOT EXISTS tickets_user ON tickets("userId");
CREATE INDEX IF NOT EXISTS trips_departure ON trips("departureTime");
CREATE TABLE IF NOT EXISTS seat_holds (id TEXT PRIMARY KEY,"ticketId" TEXT NOT NULL UNIQUE REFERENCES tickets(id),"tripId" TEXT NOT NULL REFERENCES trips(id),seat INTEGER NOT NULL,"userId" TEXT NOT NULL REFERENCES users(id),"expiresAt" TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY,"ticketId" TEXT REFERENCES tickets(id),"bookingId" TEXT REFERENCES bookings(id),"userId" TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL CHECK(amount>=0),method TEXT NOT NULL,status TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,"idempotencyKey" TEXT UNIQUE,"providerPayload" TEXT NOT NULL DEFAULT '',"createdAt" TEXT NOT NULL,"updatedAt" TEXT);
ALTER TABLE payments ADD COLUMN IF NOT EXISTS "providerPayload" TEXT NOT NULL DEFAULT '';
ALTER TABLE payments ADD COLUMN IF NOT EXISTS "updatedAt" TEXT;
CREATE TABLE IF NOT EXISTS refunds (id TEXT PRIMARY KEY,"ticketId" TEXT NOT NULL REFERENCES tickets(id),"paymentId" TEXT REFERENCES payments(id),amount INTEGER NOT NULL CHECK(amount>=0),status TEXT NOT NULL,reference TEXT,"providerStatus" TEXT,"processedAt" TEXT,"createdAt" TEXT NOT NULL);
ALTER TABLE refunds ADD COLUMN IF NOT EXISTS reference TEXT;
ALTER TABLE refunds ADD COLUMN IF NOT EXISTS "providerStatus" TEXT;
ALTER TABLE refunds ADD COLUMN IF NOT EXISTS "processedAt" TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS refunds_ticket_once ON refunds("ticketId");
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY,"ticketId" TEXT UNIQUE REFERENCES tickets(id),"paymentId" TEXT NOT NULL REFERENCES payments(id),number TEXT NOT NULL UNIQUE,amount INTEGER NOT NULL,subtotal INTEGER NOT NULL DEFAULT 0,"discountAmount" INTEGER NOT NULL DEFAULT 0,"createdAt" TEXT NOT NULL);
ALTER TABLE invoices ADD COLUMN IF NOT EXISTS subtotal INTEGER NOT NULL DEFAULT 0;
ALTER TABLE invoices ADD COLUMN IF NOT EXISTS "discountAmount" INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS voucher_usages (id TEXT PRIMARY KEY,"voucherId" TEXT NOT NULL REFERENCES vouchers(id),"userId" TEXT NOT NULL REFERENCES users(id),"ticketId" TEXT NOT NULL UNIQUE REFERENCES tickets(id),"discountAmount" INTEGER NOT NULL,"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS monthly_passes (id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL REFERENCES users(id),"routeId" TEXT NOT NULL REFERENCES routes(id),"startDate" TEXT NOT NULL,"endDate" TEXT NOT NULL,price INTEGER NOT NULL,status TEXT NOT NULL,"bookingId" TEXT REFERENCES bookings(id),"createdAt" TEXT NOT NULL);
ALTER TABLE monthly_passes ADD COLUMN IF NOT EXISTS code TEXT NOT NULL DEFAULT '';
UPDATE monthly_passes SET code='MV-' || id WHERE code='';
CREATE UNIQUE INDEX IF NOT EXISTS monthly_passes_code_unique ON monthly_passes(code);
ALTER TABLE monthly_passes ADD COLUMN IF NOT EXISTS "bookingId" TEXT REFERENCES bookings(id);
CREATE OR REPLACE VIEW passes AS SELECT * FROM monthly_passes;
CREATE TABLE IF NOT EXISTS private_files (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,"originalName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"sizeBytes" INTEGER NOT NULL CHECK("sizeBytes">0),"storagePath" TEXT NOT NULL UNIQUE,"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS discount_profiles (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES users(id),"discountType" TEXT NOT NULL,"discountEvidence" TEXT NOT NULL,"evidenceFileId" TEXT REFERENCES private_files(id),status TEXT NOT NULL DEFAULT 'pending',"reviewedBy" TEXT REFERENCES users(id),"reviewedAt" TEXT,"reviewReason" TEXT NOT NULL DEFAULT '',"createdAt" TEXT NOT NULL);
ALTER TABLE discount_profiles ADD COLUMN IF NOT EXISTS "evidenceFileId" TEXT REFERENCES private_files(id);
ALTER TABLE discount_profiles ADD COLUMN IF NOT EXISTS "reviewReason" TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS vehicle_locations (id TEXT PRIMARY KEY,"tripId" TEXT NOT NULL REFERENCES trips(id),lat DOUBLE PRECISION NOT NULL,lng DOUBLE PRECISION NOT NULL,source TEXT NOT NULL,"recordedAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES users(id),"tripId" TEXT REFERENCES trips(id),title TEXT NOT NULL,message TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0,"createdAt" TEXT NOT NULL);
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS "dedupeKey" TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS notifications_dedupe ON notifications("dedupeKey") WHERE "dedupeKey" IS NOT NULL;
CREATE TABLE IF NOT EXISTS incidents (id TEXT PRIMARY KEY,"tripId" TEXT NOT NULL REFERENCES trips(id),"driverId" TEXT NOT NULL REFERENCES users(id),type TEXT NOT NULL,description TEXT NOT NULL,"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_scans (id TEXT PRIMARY KEY,"ticketId" TEXT REFERENCES tickets(id),"tripId" TEXT NOT NULL REFERENCES trips(id),"driverId" TEXT NOT NULL REFERENCES users(id),"scannedCode" TEXT NOT NULL,result TEXT NOT NULL,"scannedAt" TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS ticket_scans_once ON ticket_scans("ticketId") WHERE result='success';
CREATE INDEX IF NOT EXISTS ticket_scans_trip_time ON ticket_scans("tripId","scannedAt");
CREATE TABLE IF NOT EXISTS complaints (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES users(id),"tripId" TEXT REFERENCES trips(id),category TEXT NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',response TEXT NOT NULL DEFAULT '',"createdAt" TEXT NOT NULL,"updatedAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES users(id),"tripId" TEXT NOT NULL REFERENCES trips(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),message TEXT NOT NULL,response TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'open',"createdAt" TEXT NOT NULL);
CREATE OR REPLACE VIEW reviews AS SELECT * FROM feedback;
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY,"userId" TEXT REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,"entityId" TEXT,details TEXT NOT NULL DEFAULT '',"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY,"userId" TEXT REFERENCES users(id),"ticketId" TEXT REFERENCES tickets(id),recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'demo',"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_changes (id TEXT PRIMARY KEY,"ticketId" TEXT NOT NULL REFERENCES tickets(id),"fromTripId" TEXT NOT NULL REFERENCES trips(id),"toTripId" TEXT NOT NULL REFERENCES trips(id),"fromSeat" INTEGER NOT NULL,"toSeat" INTEGER NOT NULL,status TEXT NOT NULL,"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS demand_forecasts (id TEXT PRIMARY KEY,"createdBy" TEXT NOT NULL REFERENCES users(id),"routeId" TEXT NOT NULL REFERENCES routes(id),"targetDate" TEXT NOT NULL,"targetHour" INTEGER NOT NULL CHECK("targetHour" BETWEEN 0 AND 23),"predictedPassengers" DOUBLE PRECISION NOT NULL,"predictedBookings" DOUBLE PRECISION NOT NULL,"predictedOccupancy" DOUBLE PRECISION NOT NULL,"demandLevel" TEXT NOT NULL,confidence DOUBLE PRECISION NOT NULL,"algorithm" TEXT NOT NULL,"metrics" TEXT NOT NULL DEFAULT '{}',"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schema_meta (key TEXT PRIMARY KEY,value TEXT NOT NULL);
